import{_ as e,a as i,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"MongoDB 数据模型与配置","description":"MongoDB 文档模型、复制分片、资源限制及配置选项。","frontmatter":{"title":"MongoDB 数据模型与配置","description":"MongoDB 文档模型、复制分片、资源限制及配置选项。","sources":[{"repository":"jekyall_blog","file":"_posts/DataStorage/mongodb/2019-03-01-mongodb-base copy.md","date":"Sun Sep 18 2022 12:21:48 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"mongodb","title":"MongoDB","link":"/topics/mongodb/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","summary":"MongoDB 文档模型、复制分片、资源限制及配置选项。","status":"active","related":[{"title":"MongoDB 操作与命令","link":"/middleware/databases/mongodb/plus/ecosystem/mongodb-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB 数据库与认证操作","link":"/middleware/databases/mongodb/plus/subjects/mongodb-index","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：版本化任务完整 CLI","link":"/middleware/databases/mongodb/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"MongoDB：连接诊断、备份恢复与自检","link":"/middleware/databases/mongodb/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：模型、索引、原子性与一致性","link":"/middleware/databases/mongodb/base/intermediate/mechanisms","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MongoDB 数据库与认证操作","link":"/middleware/databases/mongodb/plus/subjects/mongodb-index"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MongoDB 数据库与认证操作","link":"/middleware/databases/mongodb/plus/subjects/mongodb-index"},"next":false},"headers":[],"relativePath":"middleware/databases/mongodb/plus/subjects/mongodb-base-copy.md","filePath":"middleware/databases/mongodb/plus/subjects/mongodb-base-copy.md"}'),n={name:"middleware/databases/mongodb/plus/subjects/mongodb-base-copy.md"};function t(l,a,d,r,p,g){return i(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="mongodb-数据模型与配置" tabindex="-1">MongoDB 数据模型与配置 <a class="header-anchor" href="#mongodb-数据模型与配置" aria-label="Permalink to &quot;MongoDB 数据模型与配置&quot;">​</a></h1><p><span id="mongodb-base"></span></p><h2 id="mongo-db-介绍" tabindex="-1">Mongo DB 介绍 <a class="header-anchor" href="#mongo-db-介绍" aria-label="Permalink to &quot;Mongo DB 介绍&quot;">​</a></h2><ul><li>数据模型：MongoDB 使用 BSON（二进制 JSON）格式来存储数据。BSON 是一种二进制表示形式，类似于 JSON，但支持更多的数据类型，例如日期、二进制数据和特定的地理空间类型。每个文档都有一个唯一的&quot;_id&quot;字段作为主键。</li><li>集群和复制：MongoDB 支持分布式部署，可以将数据分布在多个服务器上的集群中。集群提供了高可用性和容错能力，如果某个节点发生故障，系统可以自动切换到其他节点。复制是通过将数据复制到多个服务器来实现的，其中一个服务器是主服务器，负责写入操作，其他服务器是备份服务器，用于读取操作和故障恢复。</li><li>索引和查询：MongoDB 支持多种类型的索引，包括单字段索引、组合索引、文本索引和地理空间索引等。索引可以大大提高查询性能。MongoDB 的查询语言丰富而强大，支持比较、范围、正则表达式、逻辑操作符等复杂的查询操作。</li><li>事务支持：MongoDB 从版本 4.0 开始引入了对多文档事务的支持。事务允许开发人员在多个操作上维护数据的一致性和完整性。通过事务，可以确保多个写操作要么全部成功执行，要么全部回滚，从而保持数据的一致性。</li><li>安全性：MongoDB 提供了多种安全性功能来保护数据的机密性和完整性。它支持访问控制、身份验证和角色管理，可以限制用户对数据库的访问权限。此外，MongoDB 还提供了加密通信、字段级加密和审计功能等，以增强数据的安全性。</li><li>可视化管理工具：MongoDB 提供了名为 MongoDB Compass 的官方可视化管理工具，用于浏览和操作数据库。它提供了一个直观的界面，可以执行数据查询、创建索引、监视性能和管理集群等任务。</li><li>社区支持和生态系统：MongoDB 有一个庞大的活跃社区，提供了广泛的文档、教程和示例代码。此外，还有许多第三方工具和库与 MongoDB 集成，例如 ORM（对象关系映射）工具、数据迁移工具和可视化报表工具等，为开发人员提供了更多的选择和灵活性</li></ul><h2 id="优劣" tabindex="-1">优劣 <a class="header-anchor" href="#优劣" aria-label="Permalink to &quot;优劣&quot;">​</a></h2><ul><li><p>优势</p><ul><li>灵活的数据模型：MongoDB 使用类似 JSON 的 BSON 格式存储数据，文档模型非常灵活，可以存储不同结构的数据。</li><li>高性能：MongoDB 支持水平扩展，能够处理大量的并发请求，具有很高的读写性能。</li><li>强大的查询功能：支持丰富的查询操作，包括字段查询、范围查询、正则表达式、全文搜索等。</li><li>高可用性：MongoDB 支持主从复制和分片，可以保证数据的高可用性和可靠性。</li><li>自动分片：MongoDB 可以根据数据量自动分片，简化了水平扩展的管理</li></ul></li><li><p>劣势</p><ul><li>多文档事务有额外开销：事务能力取决于服务端版本、部署拓扑与操作限制，不能用事务代替合理的数据建模。副本集和分片集群支持多文档事务；单机 standalone 部署不能直接套用这些示例。参见<a href="/middleware/databases/mongodb/base/intermediate/mechanisms#transactions">事务与数据模型</a>及<a href="https://www.mongodb.com/docs/manual/core/transactions/" target="_blank" rel="noopener noreferrer">官方事务说明</a>。</li><li>内存占用较高：MongoDB 在处理大量数据时需要较大的内存来维护索引和数据结构，会占用较多的系统资源。</li><li>学习成本：对于习惯了关系型数据库的开发人员来说，需要一定的学习成本来适应 MongoDB 的文档模型和查询语言</li></ul></li></ul><h2 id="数据库-集合-文档-限制-限制" tabindex="-1">数据库，集合，文档，限制，限制 <a class="header-anchor" href="#数据库-集合-文档-限制-限制" aria-label="Permalink to &quot;数据库，集合，文档，限制，限制&quot;">​</a></h2><blockquote><p><a href="https://docs.mongoing.com/can-kao/mongodb-limits-and-thresholds#bson-documents-bson-wen-dang" target="_blank" rel="noopener noreferrer">CN 官方文档</a></p></blockquote><ul><li>数据库（Database） <ul><li>MongoDB 可以同时管理多个数据库。每个数据库都有独立的命名空间，用于存储集合和文档。</li><li>每个数据库在物理上由一个或多个文件组成，这些文件存储实际的数据和索引。</li></ul></li><li>集合（Collection） <ul><li>集合是 MongoDB 中的一个逻辑概念，用于组织和存储一组相关的文档。</li><li>集合不要求预定义的结构，即不同的文档可以有不同的字段和结构。</li><li>集合可以通过数据库对象进行访问，例如 db.collectionName。</li></ul></li><li>文档（Document） <ul><li>文档是 MongoDB 中存储数据的基本单位，类似于关系数据库中的行。</li><li>文档使用 BSON（二进制 JSON）格式表示，是一个有序的键值对集合。</li><li>文档可以包含多种类型的数据，如字符串、整数、浮点数、布尔值、数组、嵌套文档等。</li></ul></li><li>限制（Limitations） <ul><li>单个文档的最大大小为 16MB。如果需要存储更大的数据，可以使用 GridFS 来处理大型文件。</li><li>单个集合中的文档数目没有明确的限制，但是在实际使用中，应根据系统资源和查询性能进行适度的控制。</li><li>MongoDB 支持的最大数据库数量、集合数量和索引数量都有一定的限制，具体取决于 MongoDB 的版本和配置。</li><li>单文档写操作具有原子性。MongoDB 4.0 引入副本集多文档事务，4.2 扩展到分片集群；读写关注级别、事务时限和不支持的操作仍需按目标版本核对，不能概括为所有部署“全面支持”。</li></ul></li></ul><h2 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h2><p>原记录混列了旧式 <code>dbpath/logpath/auth</code> 与点分键，不能拼成同一份配置。本节以 MongoDB 8.0 的 YAML 层级说明名称；使用其他版本先查对应手册。包安装常见文件为 <code>/etc/mongod.conf</code>，实际位置以启动参数为准。下面仅演示本地实例，不是已运行配置；目录必须存在且运行账号可写：</p><div class="language-yaml vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dbPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/data/db</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">systemLog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  destination</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/log/mongodb/mongod.log</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  logAppend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">net</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  bindIp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">27017</span></span></code></pre></div><table tabindex="0"><thead><tr><th>原记录名称</th><th>YAML中对应位置与前提</th></tr></thead><tbody><tr><td>bindIp / port</td><td><code>net.bindIp</code> / <code>net.port</code>；扩大监听范围前单独配置认证、网络访问和TLS</td></tr><tr><td>dbpath</td><td><code>storage.dbPath</code>，注意大小写</td></tr><tr><td>logpath / logappend</td><td><code>systemLog.path</code> / <code>systemLog.logAppend</code>，文件日志还需<code>destination: file</code></td></tr><tr><td>fork</td><td><code>processManagement.fork</code>；服务管理器与平台有额外约束，不应无条件设为true</td></tr><tr><td>auth / security.authorization</td><td>YAML使用<code>security</code>下的<code>authorization: enabled</code>；启用前按目标版本完成用户初始化，不能只粘贴旧<code>auth: true</code></td></tr><tr><td>replication</td><td>YAML使用<code>replication</code>下的<code>replSetName</code>；配置名称不等于已经初始化副本集</td></tr><tr><td>storage.journal.enabled</td><td>MongoDB 6.1起已移除此选项；8.0不应加入该键，不能将旧启停journal例复制过来</td></tr></tbody></table><p>点分名称用于文档索引，不代表可以直接写成顶层YAML键。核对<a href="https://www.mongodb.com/docs/v8.0/reference/configuration-options/" target="_blank" rel="noopener noreferrer">MongoDB 8.0配置文件格式与选项</a>后，再由部署拥有者确认路径、账号和拓扑；本文没有验证实际环境。</p>`,14)])])}const k=e(n,[["render",t]]);export{c as __pageData,k as default};
